#include <iostream>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, x, y;
    cin >> n >> x >> y;

    double ans = y * n / 100.0 - x;
    if (ans < 0) ans = 0;

    if (ans == (long long)ans) {
        cout << (long long)ans << "\n";
    } else {
        cout << (long long)ans + 1 << "\n";
    }

    return 0;
}

#include <iostream>
#include <cmath>

using namespace std;

int main() {
    long long n, x, y;
    cin >> n >> x >> y;
    double ans = y * n / 100.0 - x;
    if (ans < 0) ans = 0;
    if (ans == (long long)ans) cout << (long long)ans << endl;
    else cout << (long long)ans + 1 << endl;
    return 0;
}

#include <iostream>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    long long n, x, y;
    if (!(std::cin >> n >> x >> y)) return 0;

    double ans = y * n / 100.0 - x;
    if (ans < 0) ans = 0;

    long long int_part = static_cast<long long>(ans);
    if (ans == int_part) {
        std::cout << int_part;
    } else {
        std::cout << int_part + 1;
    }

    return 0;
}

